import type { FieldDef } from '@/lib/profile-schema'

/**
 * Per-school application forms.
 *
 * Every Common App member school adds its own questions on top of the shared
 * application, and they differ a lot: the set of pages is not the same school
 * to school, the question count ranges from three to twenty-odd, and the
 * wording is the school's own. A single generic template - what this app
 * shipped before - tells a student almost nothing about what they will be
 * asked.
 *
 * Questions carry `label` rather than `labelKey`: they are reproduced in the
 * asking school's own words, because a student who drafts against a translated
 * paraphrase has not prepared the answer they will paste. Our own chrome
 * around them stays translated.
 *
 * Schools without an entry fall back to the generic template in
 * lib/application-schema.ts, which is labelled as a placeholder rather than
 * passed off as the school's real questions.
 *
 * MIT is the odd one out: it does not use the Common App, so its form restates
 * the whole profile. Only its genuinely MIT-specific questions are kept here -
 * the rest is what lib/profile-schema.ts already holds.
 *
 * Re-verify each cycle: schools revise these questions annually.
 */

export interface SchoolFormPage {
  key: string
  /** The school's own page name. Not translated. */
  label: string
  kind: 'fields' | 'writing' | 'profile-pull' | 'notes'
  fields?: FieldDef[]
  /** For kind === 'profile-pull': which lib/profile-schema.ts sections to mirror read-only. */
  profileSections?: string[]
}

export interface SchoolForm {
  pages: SchoolFormPage[]
  cycle: string
  sourceNote: string
}

